			type: 'scroll',
			orient: 'vertical',
			selector: ['all', 'inverse'],
			textStyle: {fontSize: 10},
			right: 10,
			top: 20,
			bottom: 20,
		},
		tooltip: {
			trigger: 'axis',
			axisPointer: {
				type: 'line',

				link: [
					{
						xAxisIndex: [0, 1]
					}
				]
			},
			showContent: true,
			formatter: function(params) {

				if (!params || !params.length) {
					return '';
				}
				let second = params[0].axisValue;
				second = Number(second);
				let html =
					'<div style="font-size:12px;">' +
					'<b>' + second + 's</b>';
				let damageFound = false;
				params.forEach(function(param) {
					if (param.data &&
						param.data.players) {
						return;
					}
					if (param.seriesIndex === undefined) {
						return;
					}
					let series = option.series[param.seriesIndex];
					if (!series ||
						series.xAxisIndex !== 0) {
						return;
					}
					if (!damageFound) {
						html +=
							'<div style="margin-top:3px;">' +
							'<b>Damage</b></div>';
						damageFound = true;
					}
					let value = param.value;
					if (Number(value) === 0) {
						return;
					}
					if (Array.isArray(value)) {
						value = value[value.length - 1];
					}
					html +=
						'<div>' +
						'<span style="' +
						'display:inline-block;' +
						'width:8px;' +
						'height:8px;' +
						'border-radius:50%;' +
						'background:' + param.color + ';' +
						'margin-right:6px;"></span>' +
						param.seriesName + ': ' +
						Number(value).toLocaleString() +
						'</div>';
				});

				let events = [];
				option.series.forEach(function(series) {
					if (series.xAxisIndex !== 1 ||
						!series.data) {
						return;
					}
					series.data.forEach(function(event) {
						if (!event ||
							!event.value ||
							!event.players ||
							!event.players.length) {
							return;
						}
						let eventSecond = Number(event.value[0]);
						if (eventSecond === second) {
							events.push({
								name: series.name,
								players: event.players,
								color: series.itemStyle &&
									series.itemStyle.color
									? series.itemStyle.color
									: '#999'
							});
						}
					});
				});
				if (events.length) {
					html +=
						'<div style="margin-top:3px;">' +
						'<b>Events</b></div>';
					events.forEach(function(event) {
						html +=
							'<div style="margin-top:2px;">' +
							'<b>' + event.name + '</b><br>' +
							event.players.join('<br>') +
							'</div>';
					});
				}
				html += '</div>';
				return html;
			}
		},
