"""$height="500px" $width="100%" $theme="dark"/>

.page-header{
	display:flex;
	align-items:flex-start;
	justify-content:space-between;
	gap:3px
}

.page-title{
	font-size:20px;
	font-weight:800;
	color:#aeb6c2
}

.page-sub{
	font-size:12px;
	color:#94a3b8;
	margin-top:2px
}

/* TW5 tab container */
.tc-tab-set {
    margin: 8px 0 11px;
    padding: 3px;
    background: #24282e;
    border: 1px solid #454b54;
    border-radius: 10px;
}

/* Tab buttons row */
.tc-tab-buttons {
    display: flex;
    flex-wrap: wrap;
    column-gap: 4px;
    row-gap: 2px;
}

/* Individual tab button */
.tc-tab-buttons button {
    padding: 2px 6px;
    border: 0;
    border-radius: 7px;
    background: transparent;
    color: #aeb6c2;
    font-size: 11px;
    font-weight: 700;
    line-height: 1.2;
    cursor: pointer;
}

/* Hover */
.tc-tab-buttons button:hover {
    background: #353a42;
    outline: 2px solid #1a73e8;
    color: #f1f5f9;
}

/* Selected/active tab */
.tc-tab-buttons button.tc-tab-selected {
    background: #353a42;
    color: #f1f5f9;
}

/* Divider between buttons and content */
.tc-tab-divider {
    height: 1px;
    margin: 3px 0 2px;
    background: #454b54;
}

/* Tab content */
.tc-tab-content {
    margin: 4px 0 3px;
    padding: 3px 2px 2px;
}

.fight-nav{
    display:flex;
    flex-wrap:wrap;
    gap:6px;
    margin:16px 0 22px;
    padding:6px;
    background:#24282e;
    border:1px solid #454b54;
    border-radius:10px;
}

.fight-nav-btn{
    padding:7px 12px;
    border:0;
    border-radius:7px;
    background:transparent;
    color:#aeb6c2;
    font-size:11px;
    font-weight:700;
    cursor:pointer;
}

.fight-nav-btn:hover{
    background:#353a42;
    outline: 2px solid #1a73e8;
    color:#f1f5f9;
}

.fight-nav-btn.active{
    background:#353a42;
    color:#f1f5f9;
}

.metric-grid{
    display:grid;
    grid-template-columns:repeat(auto-fit, minmax(220px, 1fr));
    gap:14px;
    margin-bottom:24px;
}

.metric-card{
    background:#2b2f35;
    border:1.5px solid #454b54;
    border-radius:12px;
    padding:14px;
    transition:box-shadow .2s,transform .2s
}

.metric-card:hover{
    box-shadow:0 6px 20px rgba(0,0,0,.07);
    transform:translateY(-2px)
}

.metric-top{
    display:flex;
    align-items:center;
    justify-content:space-between;
    margin-bottom:12px
}

.metric-name{
    display:flex;
    align-items:center;
    gap:8px
}

.metric-icon{
    width:34px;
    height:34px;
    border-radius:10px;
    background:var(--ic);
    color:var(--stroke);
    display:flex;
    align-items:center;
    justify-content:center
}

.metric-label{
    font-size:12px;
    color:#aeb6c2;
    font-weight:600
}

.trend{
    font-size:11px;
    font-weight:700;
    padding:3px 7px;
    border-radius:6px
}

.trend.positive{
    color:#059669;
    background:#d1fae5
}

.trend.negative{
    color:#dc2626;
    background:#fee2e2
}

.metric-val{
    font-size:22px;
    font-weight:700;
    color:#f1f5f9;
    line-height:1;
    margin-bottom:5px
}

.metric-val-small-r{
    font-size:50%;
    font-weight:500;
    color: #d6483e;
}

.metric-val-small-b{
    font-size:50%;
    font-weight:500;
    color: #009bd9;
}

.metric-val-small-g{
    font-size:50%;
    font-weight:500;
    color: 47ab4f;
}

.metric-sub{
    font-size:11px;
    color:#aeb6c2;
    opacity:.7
}

.breakdown-row{
    display:grid;
    grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));
    gap:14px
}

.breakdown-card{
    background:#2b2f35;
    border:1.5px solid #454b54;
    border-radius:12px;
    padding:14px
}

.breakdown-title{
    font-size:13px;
    font-weight:700;
    color:#aeb6c2;
    margin-bottom:12px
}

.goals{
    display:flex;
    flex-direction:column;
    gap:12px
}

.goal-item{
    display:flex;
    flex-direction:column;
    gap:5px
}

.goal-head{
    display:flex;
    justify-content:space-between;
    font-size:12px;
    color:#aeb6c2;
    font-weight:600
}

.goal-pct{
    font-weight:700;
    color:#aeb6c2
}

.goal-track{
    background:#e2e8f0;
    border-radius:6px;
    height:7px;
    overflow:hidden
}

.goal-fill{
    height:100%;
    border-radius:6px;
    transition:width .7s cubic-bezier(.4,0,.2,1)
}

.channel-list{
    display:flex;
    flex-direction:column;
    gap:3px
}

.channel-item{
    display:grid;
    grid-template-columns:minmax(150px, 200px) auto auto;
    align-items:center;
    gap:8px
}

.ch-name{
    font-size:12px;
    color:#aeb6c2;
    font-weight:600
}

.ch-bar-wrap{
    background:#e2e8f0;
    border-radius:4px;
    height:6px;
    overflow:hidden
}

.ch-bar{
    height:100%;
    border-radius:4px;
    transition:width .6s cubic-bezier(.4,0,.2,1)
}

.ch-pct{
    font-size:11px;
    font-weight:700;
    color:#64748b;
    text-align:right
}

/* FIGHT REVIEW - COMPOSITION LAYOUT */
.composition-section{
    margin-top:24px;
}
.composition-columns{
    display:grid;
    grid-template-columns:repeat(2, minmax(0, 1fr));
    gap:14px;
    align-items:stretch;
}

/* Composition cards */
.composition-card{
    background:#2b2f35;
    border:1.5px solid #454b54;
    border-radius:12px;
    padding:14px;
    min-width:0;
}

.composition-title{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:10px;

    margin:0 0 12px;

    font-size:13px;
    font-weight:700;
    color:#f1f5f9;
}

.composition-subtitle{
    font-size:11px;
    font-weight:600;
    color:#64748b;
}

/* Squad composition */
.squad-composition{
    display:grid;
    grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));
    gap:6px 10px;
}
.squad-group{
    min-width:0;
    padding:7px 8px;
    background:#24282e;
    border:1px solid #3a3f47;
    border-radius:7px;
}

.squad-group-title{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:8px;
    margin-bottom:5px;
    font-size:11px;
    font-weight:700;
    color:#aeb6c2;
}

.squad-group-count{
    color:#f1f5f9;
    font-weight:800;
}

.squad-players{
    display:flex;
    flex-direction:column;
    gap:2px;
}

.squad-player{
    display:flex;
    align-items:center;
    gap:5px;
    min-width:0;
    font-size:10px;
    color:#94a3b8;
}

/* Enemy composition */
.enemy-compositions{
    display:flex;
    flex-direction:column;
    gap:10px;
}

.enemy-team{
    background:#24282e;
    border:1px solid #3a3f47;
    border-radius:8px;
    padding:10px;
}

.enemy-team-title{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:10px;

    margin-bottom:8px;

    font-size:11px;
    font-weight:700;
    color:#f1f5f9;
}

.enemy-team-count{
    color:#94a3b8;
    font-size:10px;
    font-weight:600;
}

/* CSS controls the number of profession columns */
.enemy-professions{
    display:grid;
    grid-template-columns:repeat(auto-fit, minmax(120px, 1fr));
    gap:5px 10px;
}

.enemy-profession{
    display:flex;
    align-items:center;
    gap:5px;

    min-width:0;
    padding:4px 2px;

    font-size:10px;
    color:#aeb6c2;
}

.enemy-profession-icon{
    flex:0 0 auto;
    display:inline-flex;
    align-items:center;
}

.enemy-profession-name{
    min-width:0;
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
}

.enemy-profession-count{
    margin-left:auto;
    color:#f1f5f9;
    font-weight:700;
    white-space:nowrap;
}

/* Hover states  */
.composition-card{
    transition:box-shadow .2s, transform .2s;
}

.composition-card:hover{
    box-shadow:0 6px 20px rgba(0,0,0,.07);
    transform:translateY(-2px);
}

.squad-group:hover,
.enemy-team:hover{
    background:#30353c;
}

/* TAG SUMMARY */

.tag-summary-list{
    display:grid;
    grid-template-columns:repeat(4, minmax(0, 1fr));
    gap:6px 12px;
}

/* Tag card */

.tag-summary-card {
    background: #2b2f35;
    border: 1.5px solid #454b54;
    border-radius: 12px;
    padding: 5px 7px;
    min-width: 0;
    transition: box-shadow .2s, transform .2s;
}

.tag-summary-card:hover{
    box-shadow:0 6px 20px rgba(0,0,0,.07);
    transform:translateY(-1px);
}

/* Header */

.tag-summary-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 2px 5px;
    margin-bottom: 0px;
    min-width: 0;
}

.tag-summary-name{
    display:flex;
    align-items:center;
    gap:3px 6px;
   min-width:0;
    font-size:12px;
    font-weight:800;
    color:#f1f5f9;
}

.tag-summary-name > span{
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
}

.tag-summary-account{
    flex:0 0 auto;
    max-width:45%;
    font-size:9px;
    font-weight:600;
    color:#64748b;
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
}

/* Metrics */

.tag-summary-metrics {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 1px 2px;
}

.tag-summary-metric:last-child {
    grid-column: span 1;
}

.tag-summary-metric {
    background: #24282e;
    border: 1px solid #3a3f47;
    border-radius: 6px;
    padding: 1px 3px;
    min-width: 0;
}

/* TW5 injects <p> around block elements */
.tag-summary-metrics > p {
    display: contents;
    margin: 0;
    padding: 0;
}

.tag-summary-label{
    margin-bottom:0px;
    font-size:8px;
    font-weight:700;
    color:#64748b;
    white-space:nowrap;
    overflow:hidden;
    text-overflow:ellipsis;
}

.tag-summary-value {
    font-size: 13px;
    font-weight: 800;
    color: #f1f5f9;
    line-height: 1;
}

/* Totals */

.tag-summary-total{
    grid-column:1 / -1;
}

/* Version notice */

.tag-version-notice{
    margin-bottom:12px;
    padding:3px 5px;
    background:#24282e;
    border:1px solid #454b54;
    border-radius:7px;
    color:#aeb6c2;
    font-size:10px;
}

/* Responsive layout */

@media (max-width:900px){

    .composition-columns{
        grid-template-columns:1fr;
    }

}

@media (max-width:700px){

    .tag-summary-list{
        grid-template-columns:1fr;
    }

}

@media (max-width:600px){

    .enemy-professions{
        grid-template-columns:repeat(2, minmax(0, 1fr));
    }

    .squad-composition{
        grid-template-columns:1fr;
    }

}

@media (max-width:500px){

    .tag-summary-metrics{
        grid-template-columns:repeat(2, minmax(0, 1fr));
    }

}

@media (max-width:400px){

    .enemy-professions{
        grid-template-columns:1fr;
    }

}
